      "label": "B",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "一阵 风吹过 天晴"
        },
        {
          "id": "V2-02",
          "zh": "我走在这 空荡路上"
        },
        {
          "id": "V2-03",
          "zh": "大步 走成风"
        },
        {
          "id": "V2-04",
          "zh": "风下 远远只剩 你站在那里"
        },
        {
          "id": "V2-05",
          "zh": "草原 一道影 拉长"
        },
        {
          "id": "V2-06",
          "zh": "远飞的鸟 落下白羽毛"
        },
        {
          "id": "V2-07",
          "zh": "我化成风 雪白色的风"
        },
        {
          "id": "V2-08",
          "zh": "随风飘"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "一阵狂风 天晴"
        },
        {
          "id": "V2-02",
          "zh": "我走在大路上"
        },
        {
          "id": "V2-03",
          "zh": "阔步向前"
        },
        {
          "id": "V2-04",
          "zh": "顺风而下 只剩你"
        },
        {
          "id": "V2-05",
          "zh": "草原上的影"
        },
        {
          "id": "V2-06",
          "zh": "迁徙的白羽"
        },
        {
          "id": "V2-07",
          "zh": "我是那阵白色的风"
        },
        {
          "id": "V2-08",
          "zh": "摇曳"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "一阵风 吹散云 天晴"
        },
        {
          "id": "V2-02",
          "zh": "我走在 长长路上"
        },
        {
          "id": "V2-03",
          "zh": "大步 向前阔步"
        },
        {
          "id": "V2-04",
          "zh": "顺风去 只剩你 独自一人"
        },
        {
          "id": "V2-05",
          "zh": "草原上 立着影"
        },
        {
          "id": "V2-06",
          "zh": "迁徙的 白色羽翼"
        },
        {
          "id": "V2-07",
          "zh": "我化作 一阵白风"
        },
        {
          "id": "V2-08",
          "zh": "轻摇曳"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "狂风一阵吹，天晴"
        },
        {
          "id": "V2-02",
          "zh": "我走在道路上"
        },
        {
          "id": "V2-03",
          "zh": "昂首阔步向前"
        },
        {
          "id": "V2-04",
          "zh": "下风处，只有你"
        },
        {
          "id": "V2-05",
          "zh": "草原上伫立的影"
        },
        {
          "id": "V2-06",
          "zh": "迁徙的白羽"
        },
        {
          "id": "V2-07",
          "zh": "我的白色之风"
        },
        {
          "id": "V2-08",
          "zh": "飘拂"
        }
      ]
    },
    {
      "label": "F",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "忽来 一阵风 放晴"
        },
        {
          "id": "V2-02",
          "zh": "我已走在 笔直路上"
        },
        {
          "id": "V2-03",
          "zh": "阔步 尘飞扬"
        },
        {
          "id": "V2-04",
          "zh": "此刻 风的下方 只剩你一人"
        },
        {
          "id": "V2-05",
          "zh": "草原 一道影 拉长"
        },
        {
          "id": "V2-06",
          "zh": "候鸟掠过 落一片白羽"
        },
        {
          "id": "V2-07",
          "zh": "我便是那 一缕白色风"
        },
        {
          "id": "V2-08",
          "zh": "随风伏"
        }
      ]
    }
  ]
}

